"film.sound": "تشغيل الصوت",
"film.mute": "إيقاف الصوت",
"intro.cta1": "ابدأ بسؤال واحد",
"intro.cta2": "شاهد مكتب اليوم",
"intro.down": "متابعة",
"sheet.label": "صفحة توضيحية من ملف قرار لمجلس الإدارة",
"sheet.head": "ملف قرار مجلس الإدارة",
"sheet.badge": "مثال",
"sheet.q": "السؤال",
"sheet.q.v": "هل يوافق مجلس الإدارة على مشروع تجريبي يستخدم الذكاء الاصطناعي التوليدي لمراجعة عقود الموردين؟",
"sheet.s": "المصادر",
"sheet.s.v": "أرشيف العقود وسياسة المشتريات ومقابلتان. كل منها موثّق بالصفحة والتاريخ.",
"sheet.a": "الافتراضات",
"sheet.a.v": "العقود بلغة واحدة. وتبقى الموافقة النهائية للإدارة القانونية. كلاهما مكتوب وكلاهما قابل للطعن.",
"sheet.o": "الخيارات",
"sheet.o.v": "<b>A</b> تجربة على فئة واحدة. <b>B</b> تجربة على جميع الفئات. <b>C</b> الانتظار ربع سنة.",
"sheet.p": "نقاط مفتوحة",
"sheet.p.v": "من يملك قائمة الاستثناءات؟ وما البيانات التي يمكن أن تغادر المؤسسة؟",
"sheet.cap": "بنية توضيحية، وليست ملف عميل مكتملًا.",
"lane.engineering": "الهندسة",
"work.kicker": "ثلاثة مخرجات محددة النطاق",
"work.h2": "سؤال واحد. مخرج واحد. شخص واحد يوقّع.",
"work.dt1": "القرار المطلوب حسمه",
"work.dt2": "المخرج",
"work.dt3": "المسؤولية",
"work.1.t": "أولويات استخدام GenAI",
"work.1.d": "أين يستحق الذكاء الاصطناعي التوليدي التجربة أولًا وأين لا يستحقها. مشكلات العمل وفرضيات القيمة ومتطلبات البيانات والوصول ومعايير قبول المشروع التجريبي.",
"work.1.o": "ملف لترتيب أولويات حالات الاستخدام.",
"work.1.r": "يتطلب مراجعة بشرية واعتمادًا من الجهة المخوّلة.",
"work.2.t": "ملف قرار مجلس الإدارة",
"work.2.d": "ما المطلوب من المجلس أن يقرره وبأي دليل. معلومات قابلة للتتبع وافتراضات وخيارات وسيناريوهات ومخاطر ونقاط مفتوحة.",
"work.2.o": "ملف قرار لمجلس الإدارة.",
"work.2.r": "تبقى سلطة القرار لدى قيادة المؤسسة.",
"work.3.t": "نموذج أولي لمسار عمل بمراجعة بشرية",
"work.3.d": "هل يمكن تشغيل سير عمل بالذكاء الاصطناعي مع بقائه قابلًا للتحقق. بيانات مصرح بها ونقاط تحكم وسجلات اختبار وملاحظات تسليم.",
"work.3.o": "وثيقة نموذج أولي واحدة لسير العمل.",
"work.3.r": "يتطلب التنفيذ والتكامل والقبول التشغيلي نطاقًا منفصلًا.",
"method.kicker": "في كل مخرج",
"method.h2": "من الإشارة إلى القرار في خمس خطوات.",
"method.label": "خطوات القرار",
"method.hint": "اختر خطوة أو استخدم مفاتيح الأسهم.",
"step.0.n": "الإشارة",
"step.1.n": "السياق",
"step.2.n": "المراجعة النقدية",
"step.3.n": "الخيارات",
"step.4.n": "القرار",
"step.0.t": "الإشارة تحتاج إلى سياق",
"step.0.b": "ابدأ بما تغيّر، ومن يتأثر، والقرار الذي يجب اتخاذه. الإشارة سؤال يستدعي البحث، وليست استنتاجًا.",
"step.1.t": "اربط الأدلة",
"step.1.b": "نظّم المدخلات المصرح بها مع مصادرها وتواريخها وحدودها. يمكن للذكاء الاصطناعي المساعدة في المقارنة والصياغة. وتبقى الأدلة الناقصة أو المتناقضة ظاهرة.",
"step.2.t": "اختبر الفرضية",
"step.2.b": "اختبر القراءة الأولى في مقابل الأدلة المضادة والتفسيرات البديلة. وتبقى الملاحظات والافتراضات الأولية والفرضيات المدعومة بالذكاء الاصطناعي منفصلة.",
"step.3.t": "اجعل الخيارات قابلة للاختبار",
"step.3.b": "قارن المسارات الممكنة وفق معايير متفق عليها والتبعيات والتعرض للخسارة. وتظل نتائج السيناريوهات مشروطة بافتراضاتها.",
"step.4.t": "يبقى القرار بشريًا",
"step.4.b": "يفحص مراجعون محددون الملف وحدوده. ويقرر العميل المخوّل. وتوضح المسؤوليات ونقاط المراجعة والخطوات التالية عملية التسليم.",
"limits.kicker": "النطاق والأدلة والمسؤولية",
"limits.h2": "الأدوات تدعم العمل. والحكم للبشر.",
"limits.lede": "نستخدم الذكاء الاصطناعي حيث يكون له غرض واضح، ونوضح الخبرة المطلوبة وما جرى اختباره.",
"limits.1.t": "يُتفق عليه قبل بدء العمل.",
"limits.1.d": "السؤال والمخرج ومعايير المراجعة والتوقيت والبيانات التي يمكننا استخدامها.",
"limits.2.t": "النماذج الأولية موسومة.",
"limits.2.d": "يبقى العمل الاستكشافي منفصلًا عن الأنظمة المعتمدة الجاهزة للإنتاج.",
"limits.3.t": "ليس رأيًا خاضعًا للتنظيم.",
"limits.3.d": "لا يُقصد بذلك تدقيق قانوني أو مشورة ضريبية أو قانونية أو استثمارية خاضعة للتنظيم. وحيث يلزم ترخيص نتحقق منه.",
"start.h2": "سؤال قرار واحد. رسوم ثابتة. ملف قرار استثماري واحد.",
"start.lede": "تحضر السؤال والمدخلات المتفق عليها. وتحصل على ملف يمكنك فحصه: مصادر وخيارات ونقاط مفتوحة. الرسوم ثابتة ومكتوبة قبل بدء أي عمل.",
"next.2": "نردّ كتابةً: النطاق والمدخلات والرسوم الثابتة.",
"start.l1": "ما الذي تغيّر أو جعلك تتوقف؟",
"start.p1": "تكفي ملاحظة واحدة.",
"start.l2": "ما الذي سيُظهر أنك اتخذت قرارًا أفضل؟",
"start.p2": "يمكن أن يبقى الهدف مفتوحًا.",
"start.l3": "التوقيت أو القيد الأساسي",
